/* 首期运行能力的静态原型：仅修改内存，不连接集群，不生成真实指标或发布。 */
const runtimeExamples = {};
const sampleCpu = [48,52,51,67,82,73,59,57,62,84,121,146,112,91,78,69,74,81,71,65,60,66,78,93,82,72,61,58,64,72];
const sampleMemory = [166,168,169,172,176,178,179,180,182,187,198,206,208,205,201,198,194,193,192,192,194,196,198,198,197,196,194,192,192,192];
function runtimeFor(name=state.currentApp){
  if(runtimeExamples[name])return runtimeExamples[name];
  const a=applicationByName(name),background=name==='worker-service';
  const number={'gateway-api':12,'marketing-web':8,'worker-service':3,'docs-site':4}[name]||0;
  const build={'gateway-api':'bld_1040','marketing-web':'bld_1037','worker-service':'bld_1035','docs-site':'bld_1038'}[name];
  const vars=[{key:'APP_ENV',value:'production',secret:false},{key:'LOG_LEVEL',value:'info',secret:false},{key:'DATABASE_URL',secret:true,configured:true}];
  const settings={kind:background?'background':'http',port:name==='marketing-web'?3000:8080,health:'/health',cpu:'500m',memory:'512Mi',domain:background?'':a.id+'.'+instancePolicy.baseDomain,customDomain:''};
  const current={id:`rel_${name}_${number}`,number,status:'success',build,config:7,time:'28 分钟前',actor:'林舟',source:'源码构建'};
  const previous={id:`rel_${name}_${number-1}`,number:number-1,status:'success',build,config:6,time:'昨天 16:20',actor:'林舟',source:'历史版本'};
  const r={status:'running',current:current.id,releases:[current,previous],next:number+1,applied:7,draft:7,vars,settings,files:[{name:'app.yaml',path:'/app/config/app.yaml',secret:false,content:'features:\n  audit: true'}],volumes:[],pending:null,metricsMissing:false,metricRange:'1h',logQuery:'',logPaused:false,events:['当前版本已通过就绪与入口检查','运行日志与资源采集正常']};
  r.snapshots={7:JSON.parse(JSON.stringify({vars,settings,files:r.files,volumes:[]})),6:JSON.parse(JSON.stringify({vars:vars.map(v=>v.key==='LOG_LEVEL'?{...v,value:'warn'}:v),settings,files:r.files,volumes:[]}))};
  r.defaultDomain=a.id+'.'+instancePolicy.baseDomain;r.placement=number?{node:instancePolicy.runtimeNode}:null;r.firstConfigConfirmed=Boolean(number);
  if(!number){r.status='unconfigured';r.current=null;r.releases=[];r.next=1;r.applied=0;r.draft=1;r.vars=[];r.files=[];r.volumes=[];r.events=[];const snapshot=JSON.parse(JSON.stringify({vars:r.vars,settings:r.settings,files:[],volumes:[]}));r.snapshots={0:JSON.parse(JSON.stringify(snapshot)),1:snapshot};}
  runtimeExamples[name]=r;return r;
}
function currentRelease(r=runtimeFor()){return r.releases.find(x=>x.id===r.current);}
function runtimeBadge(r=runtimeFor()){return badge(...({running:['运行中','green'],stopped:['已停止','gray'],deploying:['发布中','amber'],unhealthy:['不健康','red'],unknown:['状态未知','gray']}[r.status]||['未部署','gray']));}
function runtimePending(r=runtimeFor()){if(!r.current)return false;return JSON.stringify(r.snapshots[r.draft])!==JSON.stringify(r.snapshots[r.applied]);}
function runtimeMarkConfig(){const r=runtimeFor();r.draft=Math.max(r.draft,...Object.keys(r.snapshots).map(Number))+1;r.snapshots[r.draft]=JSON.parse(JSON.stringify({vars:r.vars,settings:r.settings,files:r.files,volumes:r.volumes}));r.events.unshift('运行配置已保存为 v'+r.draft+'，尚未部署');}
function runtimeBeginDeployment(buildId,configRevision,rollbackOf=''){
  const r=runtimeFor();if(!r.current&&!r.firstConfigConfirmed){go(applicationRoute(state.currentApp,'settings/runtime'));toast('请先确认运行配置，再部署镜像');return;}if(r.pending){toast('已有运行操作，请先完成当前原型操作');return;}
  const b=builds.find(x=>x.id===buildId&&x.app===state.currentApp&&x.status==='success');if(!b){toast('需要本应用已验证的镜像');return;}
  const number=r.next++;const rel={id:`rel_${state.currentApp}_${number}`,number,status:'deploying',build:buildId,config:configRevision||r.draft,time:'刚刚',actor:'林舟',source:rollbackOf?'回滚 '+rollbackOf:'手动 / 构建发布',runtimeNode:r.placement?.node||instancePolicy.runtimeNode,policyRevision:instancePolicy.revision};
  if(!r.placement)r.placement={node:rel.runtimeNode};r.releases.unshift(rel);r.pending={kind:'deploy',id:rel.id,previousStatus:r.status};r.status='deploying';r.events.unshift('正在发布 '+rel.id+'；原服务版本保留至新实例就绪');return rel;
}
function runtimeBuildCompleted(b){if(!b.autoDeploy)return;const rel=runtimeBeginDeployment(b.id,b.runtimeConfig);if(rel)b.releaseId=rel.id;}
function runtimeFinish(success){const r=runtimeFor();if(!r.pending)return;const pending=r.pending;const rel=r.releases.find(x=>x.id===pending.id);if(success){if(pending.kind==='deploy'){rel.status='success';r.current=rel.id;r.applied=rel.config;if(!r.placement)r.placement={node:rel.runtimeNode};}r.status='running';r.events.unshift('已模拟就绪与访问确认，当前版本 '+r.current);}else{if(pending.kind==='deploy')rel.status='failed';r.status=pending.previousStatus==='stopped'?'stopped':r.current?'running':'unhealthy';r.events.unshift(r.status==='running'?'新操作失败，原成功版本继续运行；示例不执行真实回滚':'新操作失败，应用保持停止或未就绪状态');}r.pending=null;render();toast('仅切换本地运行示例，未操作真实服务器');}
function runtimeConfigChanges(r=runtimeFor()){
  const before=r.snapshots[r.applied],after=r.snapshots[r.draft],changes=[];
  const labels={kind:'运行类型',port:'容器端口',health:'健康检查路径',cpu:'CPU 限额',memory:'内存限额',domain:'访问域名',customDomain:'自定义域名'};
  for(const key of Object.keys(after.settings))if(before.settings[key]!==after.settings[key])changes.push({label:labels[key]||key,before:String(before.settings[key]??'未设置'),after:String(after.settings[key]??'未设置')});
  for(const [group,field,title] of [['vars','key','变量'],['files','path','配置文件'],['volumes','path','持久卷']]){
    const keys=new Set([...before[group],...after[group]].map(v=>v[field]));
    for(const key of keys){const old=before[group].find(v=>v[field]===key),next=after[group].find(v=>v[field]===key);if(JSON.stringify(old)===JSON.stringify(next))continue;
      const describe=v=>!v?'未配置':v.secret?'敏感值 · 不显示':group==='vars'?v.value:group==='volumes'?v.size+' GiB · 保留底层数据':'普通文件 · 内容已配置';
      changes.push({label:title+' · '+key,before:describe(old),after:describe(next)+(old&&next&&(old.secret||next.secret)?'（已替换）':'')});
    }
  }return changes;
}
function runtimeReviewChanges(){
  const r=runtimeFor();if(!r.current){toast('首次部署请先构建镜像');go(applicationRoute(state.currentApp,'builds/new'));return;}const changes=runtimeConfigChanges(r);state.reviewedRuntimeConfig={app:state.currentApp,draft:r.draft,applied:r.applied};
  state.pendingRuntimeDeployment={build:currentRelease(r).build,config:r.draft,rollback:'',review:state.reviewedRuntimeConfig};
  openDialog(`<h2 id="dialog-title">检查待部署更改</h2><p>${escapeHTML(state.currentApp)} · 复用当前镜像，仅更新运行配置。保存过的更改不会自动影响线上实例。</p><div class="review-meta">${badge(changes.length+' 项更改','blue')}${badge('当前 v'+r.applied+' → 待部署 v'+r.draft,'outline')}</div>${changes.length?`<div class="change-list">${changes.map(c=>`<div class="change-item"><strong>${escapeHTML(c.label)}</strong><div class="change-values"><span><small>当前生效</small><br />${escapeHTML(c.before)}</span>${icon('arrow',16)}<span class="after"><small>部署后</small><br />${escapeHTML(c.after)}</span></div></div>`).join('')}</div>`:'<p class="review-empty">配置内容与当前生效版本一致，无需重新部署。</p>'}<p class="inline-note">${r.volumes.length?'使用持久卷，更新会短暂中断；卷内数据保留。':r.status==='stopped'?'应用当前已停止，部署后将启动实例并检查健康。':'发布时保留当前服务，等待新实例健康；资源不足可能导致发布失败。'} 敏感值不会返回到此页面。</p><div class="review-actions">${state.role!=='viewer'&&changes.length?button('放弃全部更改','runtime-discard-changes','ghost'):''}<div>${button('关闭','close-dialog')}${state.role!=='viewer'&&changes.length?button('部署 '+changes.length+' 项更改','runtime-confirm-deploy','primary'):''}</div></div>`);
  dialog.classList.add('review-dialog');
}
function runtimeConfigNotice(){const r=runtimeFor();return runtimePending(r)?`<div class="notice amber runtime-config-notice">${icon('info',16)}<p><strong>${runtimeConfigChanges(r).length} 项配置更改待部署</strong><br />编辑版本 v${r.draft} · 当前生效 v${r.applied}。保存不会重启应用。</p>${button('检查更改','runtime-review-config','sm')}</div>`:'';}
function runtimeOperationNotice(){const r=runtimeFor();return r.pending?`<div class="notice amber runtime-config-notice">${icon('clock',16)}<p><strong>${r.pending.kind==='deploy'?'新版本发布中':'运行操作处理中'}</strong><br />${r.pending.previousStatus==='stopped'?'上次运行版本':'当前服务版本'} ${r.current}；正在等待实例就绪和访问验证。</p><span class="runtime-simulation">原型场景 ${button('模拟就绪','runtime-ready','sm')}${button('模拟失败','runtime-failed','sm ghost')}</span></div>`:'';}
function runtimePage(section='overview'){
  const a=applicationByName(state.currentApp);let content;
  if(section==='overview')content=runtimeOverview(a);
  else if(section==='deployments')content=runtimeDeployments(a);
  else if(section==='logs')content=runtimelessPage(a,'logs')||runtimeLogs(a);
  else if(section==='monitoring')content=runtimelessPage(a,'monitoring')||runtimeMonitoring(a);
  else if(section==='variables')content=runtimeVariables(a);
  else content=runtimeSettings(a);
  return applicationFrame(a,content,section==='runtime-settings'?'settings':section,true);
}
function runtimelessPage(a,section='overview'){
  const r=runtimeFor(a.name);if(r.current)return '';
  return `<section class="panel empty"><h2>${section==='logs'?'暂无采集到的运行日志':section==='monitoring'?'暂无有效运行指标':r.releases.length?'首次部署未成功':'应用尚未部署'}</h2><p>${r.firstConfigConfirmed?'运行配置已确认。上传源码并完成首次构建与部署后，再查看运行结果。':'先确认应用类型、端口和健康检查；节点与镜像路径由平台管理。'}</p>${navButton('查看运行配置',applicationRoute(a.name,'settings/runtime'),'')}${state.role==='viewer'?'':navButton('上传源码',applicationRoute(a.name,'builds/new'),'primary','upload')}${r.releases.length?navButton('查看最近发布',applicationRoute(a.name,'deployments/'+r.releases[0].id),'ghost'):''}</section>`;
}
function runtimeOverview(a){const empty=runtimelessPage(a);if(empty)return empty;const r=runtimeFor(),rel=currentRelease(r),latest=builds.find(b=>b.app===a.name);const serving=r.status==='running'||r.status==='deploying'&&r.pending?.previousStatus==='running';return `${runtimeOperationNotice()}${runtimeConfigNotice()}<div class="runtime-overview-grid"><section><div class="runtime-section-title"><h2>当前运行</h2></div><dl class="runtime-facts"><dt>服务版本</dt><dd>${rel.id} ${badge('配置 v'+r.applied,'outline')}</dd><dt>镜像来源</dt><dd><a class="mono" href="#/${applicationRoute(a.name,'builds/'+rel.build)}">${rel.build} ${icon('chevron',11)}</a></dd><dt>就绪实例</dt><dd>${r.status==='stopped'?'0 / 0 · 已停止':serving?'1 / 1':'0 / 1 · 等待就绪'} <span class="muted">· ${runtimeNodeFor(a.name)}</span></dd><dt>访问地址</dt><dd>${r.settings.kind==='background'?'<span class="muted">后台进程，无公网入口</span>':`<span class="runtime-url mono">https://${r.snapshots[r.applied].settings.domain}</span><small>${r.status==='stopped'?'应用已停止，入口不可用':'HTTPS 已验证 · 示例地址'}</small>`}</dd><dt>健康检查</dt><dd>${r.settings.kind==='background'?'进程与实例状态':`HTTP ${r.snapshots[r.applied].settings.health} · ${r.snapshots[r.applied].settings.port}`}</dd><dt>最近观察</dt><dd>8 秒前 <span class="muted">· 示例快照</span></dd></dl><div class="runtime-actions">${state.role==='viewer'?'':r.status==='stopped'?button('启动应用','runtime-start','primary','arrow'):button('重启应用','runtime-restart','','history')+button('停止应用','runtime-stop','danger')} ${navButton('查看运行日志',applicationRoute(a.name,'logs'),'ghost','terminal')}</div></section><aside class="runtime-activity"><h2>近期事件</h2><ol>${r.events.slice(0,4).map((event,n)=>`<li><span>${n?'此前':'刚刚'}</span><p>${escapeHTML(event)}</p></li>`).join('')}</ol>${latest?.status==='failed'?`<div class="notice amber"><p>最近构建 ${latest.number} 失败；当前成功版本仍在运行。${navButton('查看构建',applicationRoute(a.name,'builds/'+latest.id),'ghost sm')}</p></div>`:''}</aside></div><div class="runtime-preview-strip"><div><span>CPU</span><strong>${r.status==='stopped'||r.metricsMissing?'—':'72 mCPU'}</strong><small>限额 500 mCPU</small></div><div><span>内存 working set</span><strong>${r.status==='stopped'||r.metricsMissing?'—':'192 MiB'}</strong><small>限额 512 MiB</small></div><div><span>重启次数</span><strong>0</strong><small>当前实例</small></div>${navButton('查看基础监控',applicationRoute(a.name,'monitoring'),'ghost','chevron')}</div>`;}

function runtimeDeploymentDetail(id){const a=applicationByName(state.currentApp),r=runtimeFor(),rel=r.releases.find(x=>x.id===id);if(!rel)return deniedPage('deployment-record');const pending=r.pending?.id===id;const stages=['应用配置','启动实例','健康检查',r.snapshots[rel.config].settings.kind==='background'?'确认进程':'验证访问'];return applicationFrame(a,`${pending?runtimeOperationNotice():''}<div class="page-head"><div><h2>发布 v${rel.number} ${badge(...({success:['发布成功','green'],failed:['发布失败','red'],deploying:['发布中','amber']}[rel.status]))}</h2><p class="mono">${rel.id}</p></div>${navButton('返回部署记录',applicationRoute(a.name,'deployments'),'ghost')}</div><div class="pipeline">${stages.map((name,n)=>{const type=pending?(n<2?'done':n===2?'current':''):rel.status==='success'?'done':n<2?'done':n===2?'fail':'';return `<div class="stage ${type}"><span class="stage-icon">${type==='done'?icon('check',12):type==='fail'?icon('close',12):n+1}</span><span><strong>${name}</strong><small>${type==='done'?'已确认':type==='fail'?'未通过':type==='current'?'检查中':'等待'}</small></span></div>`;}).join('')}</div><dl class="runtime-facts"><dt>镜像来源</dt><dd><a class="mono" href="#/${applicationRoute(a.name,'builds/'+rel.build)}">${rel.build}</a></dd><dt>运行配置</dt><dd>v${rel.config} · 固定版本</dd><dt>当前服务</dt><dd>${r.current||'尚无成功运行版本'}</dd><dt>运行目标</dt><dd>${runtimeNodeFor(a.name)} · 单实例</dd><dt>发起者</dt><dd>${rel.actor} · ${rel.source}</dd></dl>${rel.status==='failed'?`<div class="notice amber" style="margin-top:28px"><p>${r.current?'此原型模拟健康确认失败，原成功版本仍提供服务。':'首次发布未通过健康确认，当前没有成功服务版本。'}真实产品会展示具体事件与恢复结果，不使用示例文字代替诊断。</p></div>`:''}<div class="runtime-actions">${navButton('查看运行日志',applicationRoute(a.name,'logs'),'','terminal')}${navButton('查看基础监控',applicationRoute(a.name,'monitoring'),'ghost')}</div>`,'deployments',false);}

function runtimeDeployments(a){const r=runtimeFor();return `${runtimeOperationNotice()}${runtimeConfigNotice()}<div class="section-heading"><div><h2>部署记录</h2><p>每次发布固定镜像与运行配置版本；回滚产生新记录。</p></div></div><div class="panel table-wrap"><table><thead><tr><th>版本</th><th>发布结果</th><th>镜像构建</th><th>配置版本</th><th>来源 / 时间</th><th>操作</th></tr></thead><tbody>${r.releases.map(rel=>`<tr><td><a class="mono row-link" href="#/${applicationRoute(a.name,'deployments/'+rel.id)}"><strong>v${rel.number}</strong></a><small>${rel.id}</small>${r.current===rel.id?badge('当前服务版本','outline'):''}</td><td>${badge(...({success:['发布成功','green'],failed:['发布失败','red'],deploying:['发布中','amber']}[rel.status]))}</td><td><a href="#/${applicationRoute(a.name,'builds/'+rel.build)}" class="mono">${rel.build}</a></td><td class="mono">v${rel.config}</td><td>${escapeHTML(rel.source)}<small>${rel.actor} · ${rel.time}</small></td><td>${rel.status==='success'&&r.current!==rel.id&&state.role!=='viewer'?button('回滚到此版本','runtime-rollback-'+rel.id,'sm'):rel.status==='deploying'?button('查看进度','runtime-progress','sm'):'—'}</td></tr>`).join('')}</tbody></table></div><p class="inline-note">回滚恢复镜像和当时的运行配置；不会回退持久卷或数据库。未发布草稿保留。</p>`;}
function runtimeLogLines(a){if(a.name==='worker-service')return[{time:'10:42:01',level:'INFO',message:'worker started · release '+runtimeFor().current},{time:'10:42:02',level:'INFO',message:'queue connected, waiting for tasks'},{time:'10:42:18',level:'INFO',message:'task accepted id=job_example'},{time:'10:42:19',level:'INFO',message:'task completed id=job_example duration=812ms'}];return [{time:'10:42:01',level:'INFO',message:'application started · release '+runtimeFor().current},{time:'10:42:02',level:'INFO',message:a.name==='worker-service'?'worker queue connected':'listening on 0.0.0.0:'+runtimeFor().snapshots[runtimeFor().applied].settings.port},{time:'10:42:06',level:'INFO',message:'health check passed'},{time:'10:42:18',level:'INFO',message:'request completed method=GET path=/health status=200 duration=2ms'},{time:'10:42:24',level:'WARN',message:'upstream request retry attempt=1'},{time:'10:42:25',level:'INFO',message:'upstream request completed status=200 duration=38ms'},{time:'10:42:30',level:'INFO',message:'request completed method=GET path=/api/items status=200 duration=14ms'}];}
function runtimeLogs(a){const r=runtimeFor();return `<div class="section-heading"><div><h2>运行日志</h2><p>当前版本 ${r.current} · 保留 24 小时 / 最多 50 MiB，先达到的限制生效。</p></div>${button(r.logPaused?'恢复跟随':'暂停跟随','runtime-log-toggle','sm','terminal')}</div><div class="toolbar"><div class="filters"><select class="filter-select" aria-label="日志实例"><option>${a.name}-7f9b · 当前实例</option></select><select class="filter-select" aria-label="日志时间"><option>最近 1 小时</option></select><div class="search">${icon('search',13)}<input id="runtime-log-search" aria-label="在已加载日志中查找" placeholder="在已加载日志中查找" value="${escapeHTML(r.logQuery)}" /></div></div><span class="small muted">${r.logPaused?'已暂停跟随':'跟随中'} · 示例日志</span></div><div class="log-panel"><div class="log-toolbar"><span>${icon('terminal',13)} ${runtimeNodeFor(a.name)} / app</span><span>来源：stdout / stderr</span></div><div class="log-output" id="runtime-log-output">${runtimeLogLines(a).map((line,n)=>`<div class="log-line ${line.level==='WARN'?'error':''}" data-runtime-log="${escapeHTML(line.message.toLowerCase())}" ${line.message.toLowerCase().includes(r.logQuery.toLowerCase())?'':'hidden'}><span class="n">${n+1}</span><span class="time">${line.time}</span><span>${line.level} ${escapeHTML(line.message)}</span></div>`).join('')}<div class="runtime-log-empty" id="runtime-log-empty" ${runtimeLogLines(a).some(l=>l.message.toLowerCase().includes(r.logQuery.toLowerCase()))?'hidden':''}>当前加载的日志中没有匹配内容。</div></div></div><p class="inline-note">这里只展示应用运行日志；每次构建的日志位于“构建”详情内。停止后仍可查看保留期内的历史日志。</p>`;}
function runtimeChart(title,values,unit){const max=Math.max(...values)*1.18;const points=values.map((n,i)=>`${35+i*625/(values.length-1)},${175-n/max*140}`).join(' ');return `<section class="runtime-chart"><div><h3>${title}</h3><span>${unit} · 每分钟均值</span></div><svg viewBox="0 0 700 215" role="img" aria-label="${title}示例趋势"><g class="chart-grid"><path d="M35 35H665M35 105H665M35 175H665" /></g><text x="2" y="39">${Math.ceil(max)}</text><text x="8" y="179">0</text><polyline points="${points}" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linejoin="round"/><text x="35" y="205">${runtimeFor().metricRange==='1h'?'1 小时前':'24 小时前'}</text><text x="638" y="205">${runtimeFor().status==='stopped'?'停止前':'现在'}</text></svg></section>`;}
function runtimeMonitoring(a){const r=runtimeFor(),missing=r.metricsMissing,stopped=r.status==='stopped';const cpu=r.metricRange==='1h'?sampleCpu:sampleCpu.map((v,n)=>Math.round(v*(n<10?.6:1.2)));const memory=r.metricRange==='1h'?sampleMemory:sampleMemory.map((v,n)=>Math.round(v*(n<10?.7:1)));return `<div class="section-heading"><div><h2>基础监控</h2><p>容器资源与实例状态。数据为明确标记的静态示例。</p></div><select id="runtime-metric-range" aria-label="监控时间范围"><option value="1h" ${r.metricRange==='1h'?'selected':''}>最近 1 小时</option><option value="24h" ${r.metricRange==='24h'?'selected':''}>最近 24 小时</option></select></div><div class="runtime-monitor-summary"><span>最新采集 <strong>${missing||stopped?'无新样本':'8 秒前'}</strong></span><span>就绪实例 <strong>${r.status==='stopped'?'已停止':'1 / 1'}</strong></span><span>CPU <strong>${missing||stopped?'—':'72 mCPU / 500 mCPU'}</strong></span><span>内存 <strong>${missing||stopped?'—':'192 MiB / 512 MiB'}</strong></span></div>${missing?`<div class="panel empty"><h2>${r.status==='stopped'?'应用已停止':'暂无有效监控样本'}</h2><p>${r.status==='stopped'?'当前不展示实时资源值，历史数据按保留期提供。':'请检查执行节点的采集能力。缺失样本不会补成 0。'}</p></div>`:`${stopped?'<div class="notice"><p>应用已停止，当前资源值不展示；以下保留停止前的示例历史。</p></div>':''}<div class="runtime-chart-grid">${runtimeChart('CPU 使用量',cpu,'mCPU')}${runtimeChart('内存 working set',memory,'MiB')}</div>`}<div class="runtime-probe"><div><h3>${r.settings.kind==='background'?'进程状态':'HTTP 入口探测'}</h3><p>${r.status==='stopped'?'已停止':r.settings.kind==='background'?'进程运行中 · 不创建公网入口':'GET /health · HTTP 200 · 42 ms · 示例'}</p></div><span class="small muted">探测延迟不是业务请求 P99；首期不展示无采集来源的 QPS、磁盘/网络吞吐。</span></div><p class="inline-note">建议每 30 秒采集，保留 24 小时；图表注明聚合与采集时间。${button(r.metricsMissing?'恢复示例采集':'模拟采集缺失','runtime-metrics-toggle','ghost sm')}</p>`;}
function runtimeVariables(a){const r=runtimeFor();return `${runtimeConfigNotice()}<div class="section-heading"><div><h2>运行变量</h2><p>编辑版本 v${r.draft} · ${r.current?'生效版本 v'+r.applied:'尚未部署'}。改运行变量无需重建镜像，保存后再部署。</p></div>${state.role==='viewer'?'':button('添加变量','runtime-add-variable','primary','plus')+button('批量导入','runtime-import-variables','')}</div><div class="panel table-wrap"><table><thead><tr><th>名称</th><th>值</th><th>类型</th><th>作用阶段</th><th>操作</th></tr></thead><tbody>${r.vars.map((v,n)=>`<tr><td class="mono"><strong>${escapeHTML(v.key)}</strong></td><td class="mono">${v.secret?'•••••••• · 已配置':escapeHTML(v.value)}</td><td>${v.secret?badge('敏感值','outline'):'普通值'}</td><td>运行时</td><td>${state.role==='viewer'?'只读':button(v.secret?'替换':'编辑','runtime-edit-variable-'+n,'ghost sm')+button('删除','runtime-remove-variable-'+n,'ghost sm')}</td></tr>`).join('')}</tbody></table></div><div class="two-columns runtime-variable-notes"><section class="flat-section"><h2>构建参数与运行变量分开</h2><p>构建参数只影响镜像生成。构建密钥通过 BuildKit secret 提供，不能用 ARG 传递敏感值。</p>${navButton('查看构建设置',applicationRoute(a.name,'settings/build'),'sm')}</section><section class="flat-section"><h2>敏感值仅替换，不回显</h2><p>草稿与发布记录保存版本引用，页面和审计不返回秘密明文。回滚不会自动恢复外部凭证的有效性。</p></section></div>`;}
function runtimeSettingsNav(){const sections=[['runtime','运行设置'],['build','构建设置'],['access','成员与权限']];return `<nav class="settings-subnav" aria-label="配置分类">${sections.map(([path,label])=>`<a class="btn ghost sm" href="#/${applicationRoute(state.currentApp,'settings/'+path)}" ${currentRoute().split('?')[0].endsWith('settings/'+path)?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`;}
function runtimeSettings(a){const r=runtimeFor();return `${runtimeSettingsNav()}${!r.current?`<div class="notice"><p><strong>尚未部署 · ${r.firstConfigConfirmed?'运行配置已确认':'请确认运行配置'}</strong><br />${r.firstConfigConfirmed?'可以上传源码并发起首次部署。':'以下是默认建议，请根据程序实际行为确认。创建应用不会启动实例。'}</p></div>`:''}${runtimeConfigNotice()}<div class="section-heading"><div><h2>运行配置</h2><p>应用业务参数可编辑；平台托管配置在下方只读展示。保存不直接修改当前实例。</p></div></div><fieldset class="runtime-settings-form" ${state.role==='viewer'?'disabled':''}><section class="form-section"><h3>运行与访问</h3><div class="field"><label for="application-description">应用说明 <span class="muted">可选</span></label><input id="application-description" value="${escapeHTML(a.description)}" placeholder="简单说明这个应用的用途" /></div><div class="field-row"><div class="field"><label for="runtime-kind">应用类型</label>${r.current?`<div class="managed-value">${r.settings.kind==='background'?'后台进程':'HTTP 服务'}</div>`:`<select id="runtime-kind"><option value="http" ${r.settings.kind==='http'?'selected':''}>HTTP 服务</option><option value="background" ${r.settings.kind==='background'?'selected':''}>后台进程</option></select>`}</div><div class="field"><label>运行资源</label><div class="managed-value">由工作空间统一分配</div></div></div>${r.settings.kind==='background'?'<p class="inline-note">后台进程不创建域名或 HTTP 入口，按进程状态判断就绪。</p>':`<div class="field-row"><div class="field"><label for="runtime-port">容器监听端口</label><input id="runtime-port" type="number" value="${r.settings.port}" /></div><div class="field"><label for="runtime-health">健康检查路径</label><input id="runtime-health" value="${escapeHTML(r.settings.health)}" /></div></div><div class="field"><label>默认访问域名</label><div class="managed-value mono">${r.defaultDomain}</div><p class="hint">系统生成，不在应用中修改。平台根域名与证书方式由全局管理员管理；当前仅为示例。</p></div><div class="field"><label for="runtime-custom-domain">自定义域名 <span class="muted">可选</span></label><input id="runtime-custom-domain" value="${escapeHTML(r.settings.customDomain||'')}" placeholder="例如 api.your-domain.com" /><p class="hint">留空使用默认域名；使用自定义域名需要独立验证 DNS 与证书。</p></div>`}<div class="field-row"><div class="field"><label for="runtime-cpu">CPU 限制</label><input id="runtime-cpu" value="${r.settings.cpu}" /></div><div class="field"><label for="runtime-memory">内存限制</label><input id="runtime-memory" value="${r.settings.memory}" /></div></div><p class="inline-note">首期单实例；默认沿用镜像 ENTRYPOINT/CMD。构建与运行资源分开预留。</p></section><section class="form-section"><div class="section-heading"><div><h3>配置文件</h3><p>只读挂载；改内容后保存新版本并部署。</p></div>${button('添加文件','runtime-add-file','sm','plus')}</div>${r.files.map((f,n)=>`<div class="runtime-binding"><strong class="mono">${escapeHTML(f.path)}</strong><span>${f.secret?'敏感文件 · 仅替换':'普通配置 · 只读'}</span><span>${button('替换','runtime-edit-file-'+n,'ghost sm')}${button('移除','runtime-remove-file-'+n,'ghost sm')}</span></div>`).join('')}</section><section class="form-section"><div class="section-heading"><div><h3>持久存储</h3><p>停止、更新和回滚保留数据；本地卷不等于跨节点备份。</p></div>${button('添加卷','runtime-add-volume','sm','plus')}</div>${r.volumes.length?r.volumes.map((v,n)=>`<div class="runtime-binding"><strong class="mono">${escapeHTML(v.path)}</strong><span>${escapeHTML(v.size)} GiB · local-path · 更新使用 Recreate</span>${button('移除挂载','runtime-remove-volume-'+n,'ghost sm')}</div>`).join(''):'<p class="inline-note">尚未配置持久卷。容器临时文件不作为持久数据。</p>'}</section>${button(r.current?'保存运行配置':'保存并确认运行配置','runtime-save-settings','primary')}${!r.current&&r.firstConfigConfirmed?' '+navButton('继续上传源码',applicationRoute(a.name,'builds/new'),'','upload'):''}</fieldset>${managedResourceSummary(a)}`;}
function runtimeVariableDialog(index=-1){const r=runtimeFor(),v=r.vars[index];state.editRuntimeVariable=index;openDialog(`<h2 id="dialog-title">${v?'编辑':'添加'}运行变量</h2><p>保存后成为未部署配置；敏感旧值不回显。</p><div class="field"><label for="runtime-variable-key">名称</label><input id="runtime-variable-key" value="${v?escapeHTML(v.key):''}" ${v?'readonly':''} placeholder="例如 LOG_LEVEL" /><p class="field-error" id="runtime-variable-key-error"></p></div><div class="field"><label for="runtime-variable-value">${v?.secret?'新的值':'值'}</label><input id="runtime-variable-value" type="${v?.secret?'password':'text'}" value="${v&&!v.secret?escapeHTML(v.value):''}" autocomplete="off" /><p class="field-error" id="runtime-variable-value-error"></p></div><label class="checkbox-label"><input id="runtime-variable-secret" type="checkbox" ${v?.secret?'checked disabled':''} />敏感值，保存后不回显</label><div class="field-error" id="runtime-variable-error" role="alert" tabindex="-1"></div>${dialogFooter('runtime-save-variable','保存变量')}`);}
function runtimeHandleAction(action){
  if(!action.startsWith('runtime-')&&!action.startsWith('deploy-artifact-'))return false;
  const r=runtimeFor();
  if(action==='runtime-metrics-toggle'){r.metricsMissing=!r.metricsMissing;render();return true;}
  if(action==='runtime-log-toggle'){r.logPaused=!r.logPaused;render();return true;}
  if(action==='runtime-review-config'){runtimeReviewChanges();return true;}
  if(action==='runtime-progress'){go(applicationRoute(state.currentApp,'deployments/'+(r.pending?.id||r.current)));return true;}
  if(state.role==='viewer'){toast('当前为查看者，不能修改运行或发布');return true;}
  if(action==='runtime-ready'||action==='runtime-failed'){runtimeFinish(action==='runtime-ready');return true;}
  if(action==='runtime-discard-changes'){openDialog('<h2 id="dialog-title">放弃全部待部署更改？</h2><p>草稿将恢复为当前生效配置 v'+r.applied+'。不会停止当前实例，也不会删除卷内数据。</p>'+dialogFooter('runtime-confirm-discard','放弃更改'));return true;}
  if(action==='runtime-confirm-discard'){const checked=state.reviewedRuntimeConfig;if(!checked||checked.app!==state.currentApp||checked.draft!==r.draft||checked.applied!==r.applied){dialog.close();render();toast('配置版本已变化，请重新检查更改');return true;}const active=JSON.parse(JSON.stringify(r.snapshots[r.applied]));Object.assign(r,{vars:active.vars,settings:active.settings,files:active.files,volumes:active.volumes,draft:r.applied});dialog.close();render();toast('待部署更改已放弃，当前实例未改变');return true;}
  if(action==='runtime-add-variable'){runtimeVariableDialog();return true;}
  if(action.startsWith('runtime-edit-variable-')){runtimeVariableDialog(Number(action.slice('runtime-edit-variable-'.length)));return true;}
  if(action.startsWith('runtime-focus-variable-')){document.querySelector('#runtime-variable-'+action.slice('runtime-focus-variable-'.length))?.focus();return true;}
  if(action==='runtime-save-variable'){
    const key=document.querySelector('#runtime-variable-key').value.trim(),value=document.querySelector('#runtime-variable-value').value,secret=document.querySelector('#runtime-variable-secret').checked,index=state.editRuntimeVariable,errors=[];
    if(!/^[A-Za-z_][A-Za-z0-9_]*$/.test(key))errors.push({field:'key',message:'名称需以字母或下划线开头，只含字母、数字与下划线。'});
    else if(index<0&&r.vars.some(v=>v.key===key))errors.push({field:'key',message:'名称已存在，请编辑已有变量或使用其他名称。'});
    if(!value)errors.push({field:'value',message:'请填写变量值；替换敏感变量时需提供新的值。'});
    for(const field of ['key','value']){document.querySelector('#runtime-variable-'+field).removeAttribute('aria-invalid');document.querySelector('#runtime-variable-'+field+'-error').textContent='';}
    const summary=document.querySelector('#runtime-variable-error');summary.innerHTML='';
    if(errors.length){for(const error of errors){const input=document.querySelector('#runtime-variable-'+error.field);input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby','runtime-variable-'+error.field+'-error');document.querySelector('#runtime-variable-'+error.field+'-error').textContent=error.message;}summary.innerHTML='请修正以下字段：'+errors.map(e=>`<button class="error-field-link" data-action="runtime-focus-variable-${e.field}">${e.field==='key'?'名称':'值'}</button>`).join('、');if(errors.length>1)summary.focus();else document.querySelector('#runtime-variable-'+errors[0].field).focus();return true;}
    const v=secret?{key,secret:true,configured:true,version:Math.max(...Object.keys(r.snapshots).map(Number))+1}:{key,value,secret:false};if(index>=0)r.vars[index]=v;else r.vars.push(v);runtimeMarkConfig();dialog.close();render();toast('已保存本地变量示例，运行版本未改变');return true;
  }
  if(action==='runtime-import-variables'){openDialog('<h2 id="dialog-title">批量导入变量</h2><p>本原型演示单行 KEY=VALUE；先预览差异，不会导出已有敏感明文。</p><div class="field"><label for="runtime-env-import">.env 内容</label><textarea id="runtime-env-import" rows="6" placeholder="LOG_LEVEL=debug"></textarea></div>'+dialogFooter('runtime-preview-import','预览导入'));return true;}
  if(action==='runtime-preview-import'){const lines=document.querySelector('#runtime-env-import').value.split('\n').filter(l=>l.trim()&&!l.trim().startsWith('#'));const entries=lines.map(l=>{const n=l.indexOf('=');return{key:l.slice(0,n).trim(),value:l.slice(n+1)}});if(!entries.length||entries.some(e=>!e.value||!/^[A-Za-z_][A-Za-z0-9_]*$/.test(e.key))||new Set(entries.map(e=>e.key)).size!==entries.length){toast('原型仅支持不重复的单行 KEY=VALUE');return true;}if(entries.some(e=>r.vars.find(v=>v.key===e.key)?.secret)){toast('敏感变量请单独替换，不能通过普通批量导入覆盖');return true;}state.pendingEnvImport=entries;openDialog('<h2 id="dialog-title">导入预览</h2><p>只新增或修改以下键，不删除未出现的已有变量。</p><div class="code-box"><pre>'+entries.map(e=>escapeHTML(e.key)+' · '+(r.vars.some(v=>v.key===e.key)?'修改':'新增')).join('\n')+'</pre></div>'+dialogFooter('runtime-apply-import','确认保存为配置版本'));return true;}
  if(action==='runtime-apply-import'){for(const e of state.pendingEnvImport||[]){const index=r.vars.findIndex(v=>v.key===e.key);const value={...e,secret:false};if(index>=0)r.vars[index]=value;else r.vars.push(value);}state.pendingEnvImport=[];runtimeMarkConfig();dialog.close();render();return true;}
  if(action==='runtime-save-settings'){const firstConfirmation=!r.firstConfigConfirmed;const cpu=document.querySelector('#runtime-cpu').value.trim(),memory=document.querySelector('#runtime-memory').value.trim();if(!/^[1-9]\d*m$/.test(cpu)||!/^\d+(Mi|Gi)$/.test(memory)||parseInt(memory)<=0){toast('请使用有效的 CPU m 和内存 Mi/Gi 单位');return true;}if(r.settings.kind!=='background'){const port=Number(document.querySelector('#runtime-port').value),health=document.querySelector('#runtime-health').value.trim(),customDomain=document.querySelector('#runtime-custom-domain').value.trim(),domain=customDomain||r.defaultDomain;if(!Number.isInteger(port)||port<1||port>65535||!health.startsWith('/')||!domain||/[:/\s]/.test(domain)){toast('请检查端口、健康路径与不含协议的域名');return true;}Object.assign(r.settings,{port,health,domain,customDomain});}Object.assign(r.settings,{cpu,memory});if(r.settings.kind==='background')Object.assign(r.settings,{domain:'',customDomain:''});applicationByName(state.currentApp).description=document.querySelector('#application-description').value.trim();r.firstConfigConfirmed=true;const changed=JSON.stringify({vars:r.vars,settings:r.settings,files:r.files,volumes:r.volumes})!==JSON.stringify(r.snapshots[r.draft]);if(changed||firstConfirmation)runtimeMarkConfig();render();toast(changed||firstConfirmation?'配置已确认保存，部署后才会生效':'已保存应用说明，运行配置未改变');return true;}

  if(/^runtime-remove-(variable|file|volume)-/.test(action)){const match=action.match(/^runtime-remove-(variable|file|volume)-(\d+)$/);if(!match)return true;const kind=match[1],index=Number(match[2]),item=(kind==='variable'?r.vars:kind==='file'?r.files:r.volumes)[index];state.pendingRuntimeRemove={kind,index};openDialog(`<h2 id="dialog-title">${kind==='variable'?'删除变量':'移除挂载'}？</h2><p>对象：${escapeHTML(item.key||item.path)}。保存后仍需部署才会影响运行实例。${kind==='volume'?'只解除挂载，底层数据卷保留。':''}</p>${dialogFooter('runtime-confirm-remove','保存更改')}`);return true;}
  if(action==='runtime-confirm-remove'){const req=state.pendingRuntimeRemove;(req.kind==='variable'?r.vars:req.kind==='file'?r.files:r.volumes).splice(req.index,1);runtimeMarkConfig();dialog.close();render();return true;}
  if(action==='runtime-add-file'||action==='runtime-add-volume'||action.startsWith('runtime-edit-file-')){const file=action!=='runtime-add-volume';const index=action.startsWith('runtime-edit-file-')?Number(action.slice('runtime-edit-file-'.length)):-1;const old=index>=0?r.files[index]:null;state.editRuntimeFile=index;openDialog(`<h2 id="dialog-title">${file?old?'替换配置文件':'添加配置文件':'添加持久卷'}</h2><p>${file?'配置只读挂载，敏感旧内容不回显。':'本地卷绑定当前节点，更新会短暂中断；停止和回滚保留数据。'}</p><div class="field"><label for="runtime-binding-path">容器内挂载路径</label><input id="runtime-binding-path" value="${old?escapeHTML(old.path):''}" ${old?'readonly':''} placeholder="${file?'/app/config/extra.yaml':'/app/data'}" /></div>${file?`<div class="field"><label for="runtime-file-content">${old?.secret?'新的文件内容':'文件内容'}</label><textarea id="runtime-file-content" rows="5">${old&&!old.secret?escapeHTML(old.content||''):''}</textarea></div><label class="checkbox-label"><input id="runtime-file-secret" type="checkbox" ${old?.secret?'checked disabled':''} />敏感配置文件</label>`:'<div class="field"><label for="runtime-volume-size">容量 GiB</label><input id="runtime-volume-size" type="number" min="1" value="1" /></div>'}${dialogFooter(file?'runtime-save-file':'runtime-save-volume','保存到配置版本')}`);return true;}
  if(action==='runtime-save-file'||action==='runtime-save-volume'){const path=document.querySelector('#runtime-binding-path').value.trim(),file=action==='runtime-save-file',index=file?state.editRuntimeFile:-1;if(path==='/'||!path.startsWith('/')||path.includes('..')||/^\/(proc|sys|dev)(\/|$)/.test(path)||(file?r.files:r.volumes).some((x,n)=>x.path===path&&n!==index)){toast('请填写有效且不重复的容器内路径');return true;}if(file){const content=document.querySelector('#runtime-file-content').value;if(!content){toast('请填写文件内容');return true;}const secret=document.querySelector('#runtime-file-secret').checked;const entry=secret?{name:path.split('/').pop(),path,secret:true,version:Math.max(...Object.keys(r.snapshots).map(Number))+1}:{name:path.split('/').pop(),path,secret:false,content};if(index>=0)r.files[index]=entry;else r.files.push(entry);}else{const size=Number(document.querySelector('#runtime-volume-size').value);if(!Number.isInteger(size)||size<1){toast('容量需为正整数 GiB');return true;}r.volumes.push({path,size});}runtimeMarkConfig();dialog.close();render();return true;}
  if(action==='runtime-deploy-config'){runtimeReviewChanges();return true;}
  if(action.startsWith('deploy-artifact-')||action.startsWith('runtime-rollback-')){let build=currentRelease(r).build,config=r.draft,rollback='';if(action.startsWith('deploy-artifact-'))build=action.slice('deploy-artifact-'.length);if(action.startsWith('runtime-rollback-')){const rel=r.releases.find(x=>x.id===action.slice('runtime-rollback-'.length));if(!rel||rel.status!=='success')return true;build=rel.build;config=rel.config;rollback=rel.id;}state.pendingRuntimeDeployment={build,config,rollback};openDialog(`<h2 id="dialog-title">${rollback?'回滚到选定版本？':'部署这个版本？'}</h2><p>将使用镜像 ${escapeHTML(build)} 与运行配置 v${config} 创建发布。${rollback?'未发布草稿保留，持久数据不回退。':'镜像无需重新构建，当前实例在新版本就绪前继续服务。'}</p>${dialogFooter('runtime-confirm-deploy',rollback?'确认回滚':'确认部署')}`);return true;}
  if(action==='runtime-confirm-deploy'){const req=state.pendingRuntimeDeployment;if(!req||req.review&&(req.review.app!==state.currentApp||req.review.draft!==r.draft||req.review.applied!==r.applied)){dialog.close();render();toast('配置版本已变化，请重新检查更改');return true;}dialog.close();const rel=runtimeBeginDeployment(req.build,req.config,req.rollback);if(rel)go(applicationRoute(state.currentApp,'deployments/'+rel.id));return true;}
  if(['runtime-restart','runtime-start','runtime-stop'].includes(action)){state.pendingRuntimeOperation=action;openDialog(`<h2 id="dialog-title">${action==='runtime-stop'?'停止应用？':action==='runtime-start'?'启动应用？':'重启应用？'}</h2><p>${action==='runtime-stop'?'应用将不再提供服务，配置、发布记录和持久卷保留。':'将使用当前服务版本，单实例可能短暂中断。'}此操作只演示本地流程。</p>${dialogFooter('runtime-confirm-operation','确认')}`);return true;}
  if(action==='runtime-confirm-operation'){dialog.close();if(state.pendingRuntimeOperation==='runtime-stop'){if(r.pending?.kind==='deploy'){const rel=r.releases.find(x=>x.id===r.pending.id);rel.status='failed';rel.source+=' · 被停止操作终止';}r.status='stopped';r.pending=null;r.events.unshift('已模拟停止确认，持久数据保留');}else{r.pending={kind:state.pendingRuntimeOperation==='runtime-start'?'start':'restart',id:r.current,previousStatus:r.status};r.status='deploying';}go(applicationRoute());return true;}
  return true;
}
function runtimeHandleChange(event){const el=event.target;if(el.id==='runtime-kind'&&!runtimeFor().current){const r=runtimeFor();r.settings.kind=el.value;r.firstConfigConfirmed=false;if(el.value==='http'&&!r.settings.domain)r.settings.domain=r.defaultDomain;render();return true;}if(el.id==='runtime-metric-range'){runtimeFor().metricRange=el.value;render();return true;}if(el.id==='runtime-variable-secret'){document.querySelector('#runtime-variable-value').type=el.checked?'password':'text';return true;}if(el.id==='auto-deploy'){state.autoDeploy=el.checked;render();return true;}return false;}
function runtimeHandleInput(event){if(event.target.id==='runtime-log-search'){const r=runtimeFor();r.logQuery=event.target.value;const rows=[...document.querySelectorAll('[data-runtime-log]')];rows.forEach(line=>line.hidden=!line.dataset.runtimeLog.includes(r.logQuery.toLowerCase()));const empty=document.querySelector('#runtime-log-empty');if(empty)empty.hidden=rows.some(line=>!line.hidden);return true;}return false;}
